describe('Image Upload Preview', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('input[type="file"]').as('fileInput');
    cy.get('[data-testid="image-preview"]').as('preview');
    cy.get('button[type="submit"]').as('submitBtn');
  });

  it('should display image preview after selecting a valid image file', () => {
    const fileName = 'test-image.png';

    cy.get('@fileInput').selectFile('cypress/fixtures/test-image.png', { force: true });

    cy.get('@preview').should('be.visible');
    cy.get('@preview').find('img').should('have.attr', 'src').and('include', 'blob:');
    cy.get('@preview').find('img').should('have.css', 'max-width', '300px');
  });

  it('should display preview for multiple image formats', () => {
    const imageFormats = [
      'cypress/fixtures/test-image.jpg',
      'cypress/fixtures/test-image.gif',
      'cypress/fixtures/test-image.webp'
    ];

    imageFormats.forEach((imagePath) => {
      cy.get('@fileInput').selectFile(imagePath, { force: true });
      cy.get('@preview').should('be.visible');
      cy.get('@preview').find('img').should('have.attr', 'src');
    });
  });

  it('should clear preview when file input is cleared', () => {
    cy.get('@fileInput').selectFile('cypress/fixtures/test-image.png', { force: true });
    cy.get('@preview').should('be.visible');

    cy.get('@fileInput').invoke('val', '').trigger('change');
    cy.get('@preview').should('not.be.visible');
  });

  it('should not display preview for non-image files', () => {
    cy.get('@fileInput').selectFile('cypress/fixtures/document.pdf', { force: true });
    cy.get('@preview').should('not.exist');
    cy.get('[data-testid="error-message"]').should('contain', 'Please select a valid image file');
  });

  it('should maintain preview when form validation fails', () => {
    cy.get('@fileInput').selectFile('cypress/fixtures/test-image.png', { force: true });
    cy.get('@preview').should('be.visible');

    cy.get('@submitBtn').click();
    cy.get('[data-testid="form-error"]').should('be.visible');
    cy.get('@preview').should('still.be.visible');
    cy.get('@preview').find('img').should('have.attr', 'src');
  });

  it('should display preview with correct dimensions for large image', () => {
    cy.get('@fileInput').selectFile('cypress/fixtures/large-image.png', { force: true });

    cy.get('@preview').should('be.visible');
    cy.get('@preview').find('img').then(($img) => {
      expect($img[0].naturalWidth).to.be.greaterThan(0);
      expect($img[0].naturalHeight).to.be.greaterThan(0);
    });
  });
});
